INSERT INTO ALOCACOES_PROJETO (PROJETO_ID, USUARIO_ID, PERCENTUAL_ALOCACAO, DATA_INICIO, STATUS)
SELECT * FROM (SELECT (SELECT ID FROM PROJETOS WHERE NOME = 'Portal Cliente' LIMIT 1) AS PROJETO_ID, (SELECT ID FROM FUNCIONARIO WHERE EMAIL = (SELECT EMAIL FROM (SELECT EMAIL FROM FUNCIONARIO WHERE TIPO_PERFIL='recurso' LIMIT 0,1) as sub) LIMIT 1) AS USUARIO_ID, 50 AS PERCENTUAL_ALOCACAO, '2024-01-01' AS DATA_INICIO, 'ativo' AS STATUS) as tmp
WHERE NOT EXISTS (SELECT 1 FROM ALOCACOES_PROJETO a JOIN FUNCIONARIO f ON f.ID = a.USUARIO_ID WHERE a.PROJETO_ID = (SELECT ID FROM PROJETOS WHERE NOME = 'Portal Cliente' LIMIT 1) AND f.EMAIL = (SELECT EMAIL FROM (SELECT EMAIL FROM FUNCIONARIO WHERE TIPO_PERFIL='recurso' LIMIT 0,1) as sub));
