INSERT INTO LANCAMENTOS_HORAS (USUARIO_ID, PROJETO_ID, DESCRICAO_ATIVIDADE, CATEGORIA, DURACAO_MINUTOS, DATA_LANCAMENTO, STATUS)
SELECT * FROM (SELECT (SELECT ID FROM FUNCIONARIO WHERE TIPO_PERFIL='recurso' LIMIT 0,1) AS USUARIO_ID, (SELECT ID FROM PROJETOS WHERE NOME = 'Portal Cliente' LIMIT 1) AS PROJETO_ID, 'Horas apontadas - Portal Cliente - 1' AS DESCRICAO_ATIVIDADE, 'desenvolvimento' AS CATEGORIA, 300 AS DURACAO_MINUTOS, '2024-09-01' AS DATA_LANCAMENTO, 'aprovado' AS STATUS) AS tmp
WHERE NOT EXISTS (SELECT 1 FROM LANCAMENTOS_HORAS l JOIN FUNCIONARIO f ON f.ID = l.USUARIO_ID JOIN PROJETOS pr ON pr.ID = l.PROJETO_ID WHERE f.TIPO_PERFIL='recurso' AND pr.NOME='Portal Cliente' AND l.DESCRICAO_ATIVIDADE='Horas apontadas - Portal Cliente - 1' AND l.DATA_LANCAMENTO='2024-09-01');
